import hashlib, json
from pathlib import Path
root = Path('products/services/world-bank-buyer-acceptance')
raw = (root / 'raw/procurement-feed.json').read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '4f320b60ed83b0861f177faad315db7fb9298263930c88a1feb91ea3fb306e73', digest
feed = json.loads(raw)

def shape(value, depth=3):
    result = {'type': type(value).__name__}
    if isinstance(value, (dict, list)):
        result['length'] = len(value)
    if depth and isinstance(value, list):
        result['first_entry_shapes'] = [shape(entry, depth - 1) for entry in value[:3]]
    if depth and isinstance(value, dict):
        result['fields'] = {key: shape(entry, depth - 1) for key, entry in list(value.items())[:16]}
    return result

report = {'source_sha256': digest, 'reported_numeric_metadata': {key: feed[key] for key in ('total', 'rows', 'page', 'os') if type(feed.get(key)) is int}, 'procnotices_shape': shape(feed.get('procnotices')), 'scope': 'One saved response. Container structure and reported metadata do not establish current opportunities or market coverage.'}
serialized = json.dumps(report, indent=2) + '\n'
(root / 'feed-structure-readback.json').write_text(serialized, encoding='utf-8')
print(serialized)
